//! BIP34 coinbase height encoding.
//!
//! Height 0 is OP_0. Heights 1 through 16 are OP_1 through OP_16.
//! Each of those is followed by 0xff so the coinbase script is at least two bytes.
//! A taller height is one length byte plus the minimal little-endian magnitude.
//! When the high bit of the last magnitude byte is set, a trailing 0x00 keeps the
//! number non-negative. Height 128 is 028000. Height 32768 is 03008000.

use blvm_consensus::bip_validation::encode_bip34_coinbase_script;

#[test]
fn the_short_heights_use_opcodes_and_the_sign_bit_adds_a_zero_byte() {
    assert_eq!(encode_bip34_coinbase_script(0), vec![0x00, 0xff]);
    assert_eq!(encode_bip34_coinbase_script(1), vec![0x51, 0xff]);
    assert_eq!(encode_bip34_coinbase_script(16), vec![0x60, 0xff]);
    assert_eq!(encode_bip34_coinbase_script(17), vec![0x01, 0x11]);
    assert_eq!(encode_bip34_coinbase_script(127), vec![0x01, 0x7f]);
    assert_eq!(encode_bip34_coinbase_script(128), vec![0x02, 0x80, 0x00]);
    assert_eq!(
        encode_bip34_coinbase_script(32768),
        vec![0x03, 0x00, 0x80, 0x00]
    );
}

#[test]
fn every_height_through_65535_is_that_minimal_push() {
    assert_eq!(ROWS.len(), 65536);
    for (i, &(height, script)) in ROWS.iter().enumerate() {
        assert_eq!(height, i as u64);
        assert_eq!(
            hex::encode(encode_bip34_coinbase_script(height)),
            script,
            "height {height}"
        );
    }
}

#[test]
fn wider_magnitudes_pad_the_sign_bit_and_grow_by_one_byte_at_each_boundary() {
    for &(height, script) in WIDE {
        assert_eq!(
            hex::encode(encode_bip34_coinbase_script(height)),
            script,
            "height {height}"
        );
    }
}

